 public sealed class RepeatingTodosEndpointTests : IClassFixture<ApiTestFactory>
 {
     private const string ValidBody =
         """{"title":"Týdenní report","priority":"High","firstDueAtUtc":"2026-10-26T09:00:00Z","repeatCount":3}""";

